    if ($response.success -ne $true) {
        $messages = @($response.errors | ForEach-Object { $_.message }) -join '; '
        if ([string]::IsNullOrWhiteSpace($messages)) {
            $messages = 'Cloudflare returned an unsuccessful response.'
        }
        throw $messages
    }

    return $response
}

